            g_free(file_path);

            if (result == -1 || WIFEXITED(result) && WEXITSTATUS(result) != 0) {
                GtkWidget *dialog = gtk_text_editor_new();
                gtk_text_editor_load_contents(GTK_TEXT_EDITOR(dialog), item_name);
