void on_tree_view_row_activated(GtkTreeView *tree_view, GtkTreePath *tree_path_UNUSED, GtkTreeViewColumn *column, gpointer user_data) {
    GtkTreeIter iter;
    GtkTreeModel *model = gtk_tree_view_get_model(tree_view);
    gchar *item_name = NULL;

    if (gtk_tree_model_get_iter(model, &iter, tree_path_UNUSED)) {
        gtk_tree_model_get(model, &iter, ITEM_NAME_COLUMN, &item_name, -1);
        if (item_name && strchr(item_name, '\n') != NULL) {
            gchar *file_path = get_file_path_from_item_name(item_name); // Assume this helper exists
            gchar *uri = g_filename_to_uri(file_path, NULL, NULL);
            GAppLaunchContext *context = g_app_launch_context_new();
            gboolean success = g_app_info_launch_default_for_uri(uri, G_APP_LAUNCH_CONTEXT(context));

            if (!success) {
                GtkWidget *dialog = gtk_text_view_new();
                GtkTextBuffer *buffer = gtk_text_buffer_new(NULL);
                gtk_text_buffer_set_text(buffer, item_name, -1);
                gtk_text_view_set_buffer(GTK_TEXT_VIEW(dialog), buffer);
                gtk_text_view_set_editable(GTK_TEXT_VIEW(dialog), TRUE);

                GtkWidget *dialog_window = gtk_window_new(GTK_WINDOW_TOPLEVEL);
                gtk_window_set_title(GTK_WINDOW(dialog_window), "Edit Text");
                gtk_container_add(GTK_CONTAINER(dialog_window), dialog);
                g_signal_connect(dialog_window, "destroy", G_CALLBACK(gtk_widget_destroy), dialog_window);
                gtk_widget_show_all(dialog_window);

                GtkWidget *save_button = gtk_button_new_with_label("Save");
                g_signal_connect(save_button, "clicked", G_CALLBACK(save_edited_text), &item_name);
                gtk_box_pack_end(GTK_BOX(gtk_dialog_get_action_area(GTK_DIALOG(dialog_window))), save_button, FALSE, FALSE, 0);
                gtk_widget_show(save_button);
            }

            g_free(file_path);
            g_free(uri);
            g_object_unref(context);
        }

        g_free(item_name);
    }
}

#include <gtk/gtk.h>
#include <glib.h>
#include <stdlib.h>

static gchar *problem_item_name = NULL;

void on_row_activated(GtkTreeView *tree_view, GtkTreePath *tree_path_UNUSED, GtkTreeViewColumn *column, gpointer user_data) {
    if (!problem_item_name) {
        return;
    }

    if (g_strrstr(problem_item_name, "\n")) {
        gchar *file_path = g_strdup_printf("%s.txt", problem_item_name);
        GError *error = NULL;
        gboolean success = gtk_show_uri_on_window(NULL, "file://"file_path, GDK_CURRENT_TIME, &error);

        if (!success) {
            GtkWidget *dialog;
            GtkWidget *text_view;
            GtkTextBuffer *buffer;
            GtkTextIter start, end;

            dialog = gtk_dialog_new_with_buttons("Edit Text",
                                                 NULL,
                                                 GTK_DIALOG_MODAL,
                                                 GTK_STOCK_SAVE,
                                                 GTK_RESPONSE_ACCEPT,
                                                 GTK_STOCK_CANCEL,
                                                 GTK_RESPONSE_REJECT,
                                                 NULL);

            GtkWidget *content_area = gtk_dialog_get_content_area(GTK_DIALOG(dialog));
            GtkWidget *scrolled_window = gtk_scrolled_window_new(NULL, NULL);
            text_view = gtk_text_view_new();
            gtk_text_view_set_wrap_mode(GTK_TEXT_VIEW(text_view), GTK_WRAP_WORD);
            gtk_container_add(GTK_CONTAINER(scrolled_window), text_view);
            gtk_container_add(GTK_CONTAINER(content_area), scrolled_window);
            gtk_widget_show_all(dialog);

            buffer = gtk_text_view_get_buffer(GTK_TEXT_VIEW(text_view));
            gtk_text_buffer_get_start_iter(buffer, &start);
            gtk_text_buffer_get_end_iter(buffer, buffer, &end);
            gtk_text_buffer_delete(buffer, &start, &end);
            gtk_text_buffer_insert_at_cursor(buffer, problem_item_name, -1);

            gint response = gtk_dialog_run(GTK_DIALOG(dialog));
            if (response == GTK_RESPONSE_ACCEPT) {
                gtk_text_buffer_get_start_iter(buffer, &start);
                gtk_text_buffer_get_end_iter(buffer, &end);
                gchar *new_text = gtk_text_buffer_get_text(buffer, &start, &end, FALSE);

                if (problem_item_name) {
                    g_free(problem_item_name);
                }

                problem_item_name = new_text;
            }

            gtk_widget_destroy(dialog);
        }

        g_free(file_path);
    }

    g_free(problem_item_name);
    problem_item_name = NULL;
}
